#define DMA_CH2_BASE              0x00001040U     //DMA_CH_REGS
#define ADCARESULT_BASE           0x00001800U     //ADC_LITE_RESULT_REGS
#define PWM1_BASE                 0x00004000U     //MCPWM_6CH_REGS
#define PWM3_BASE                 0x00004800U     //MCPWM_2CH_REGS
