//*************************************************************************************************
//
// The following are defines for the SYSCTL register offsets
//
//*************************************************************************************************
#define SYSCTL_O_PARTIDL                0x2U    // Lower 32-bit of Device PART Identification
                                                // Number
#define SYSCTL_O_PARTIDH                0x4U    // Upper 32-bit of Device PART Identification
                                                // Number
#define SYSCTL_O_REVID                  0x6U    // Device Revision Number
#define SYSCTL_O_DC_MEMORY              0xEU    // Device Capability: Memory Blocks Customization
#define SYSCTL_O_PERCNF                 0x10U   // Peripheral Configuration register - GPIO
#define SYSCTL_O_TRIMERRSTS             0x12U   // TRIM Error Status register
#define SYSCTL_O_SOFTPRES_PROC_INFRA    0x1EU   // Processing and Infra Blocks Software Reset
                                                // register
#define SYSCTL_O_SOFTPRES_CTRL_PERIPH   0x20U   // Control Peripherals Software Reset register
#define SYSCTL_O_SOFTPRES_COMM_PERIPH   0x22U   // Communication Peripherals Software Reset
                                                // register
#define SYSCTL_O_SOFTPRES_JTAG          0x24U   // JTAG Software Reset register
#define SYSCTL_O_TAP_STATUS             0x28U   // Status of JTAG State machine & Debugger Connect
#define SYSCTL_O_ECAPTYPE               0x2AU   // Configures ECAP Type for the device
#define SYSCTL_O_TAP_CONTROL            0x2CU   // Disable TAP control

#define SYSCTL_O_CLKCFGLOCK      0x0U    // Lock bit for CLKCFG registers
#define SYSCTL_O_CLKSRCCTL1      0x2U    // Clock Source Control register-1
#define SYSCTL_O_CLKSRCCTL3      0x6U    // Clock Source Control register-3
#define SYSCTL_O_SYSPLLCTL       0x8U    // SYSPLL Control register
#define SYSCTL_O_SYSPLLMULT      0xAU    // SYSPLL Multiplier register
#define SYSCTL_O_SYSPLLSTS       0xCU    // SYSPLL Status register
#define SYSCTL_O_SYSCLKDIVSEL    0xEU    // System Clock Divider Select register
#define SYSCTL_O_XCLKOUTDIVSEL   0x12U   // XCLKOUT Divider Select register
#define SYSCTL_O_LOSPCP          0x14U   // Low Speed Clock Source Prescalar
#define SYSCTL_O_MCDCR           0x16U   // Missing Clock Detect Control Register
#define SYSCTL_O_X1CNT           0x18U   // 10-bit Counter on X1 Clock
#define SYSCTL_O_XTALCR          0x1AU   // XTAL Control Register
#define SYSCTL_O_XTALCR2         0x1CU   // XTAL Control Register for pad init
#define SYSCTL_O_CLKFAILCFG      0x1EU   // Clock Fail cause Configuration
#define SYSCTL_O_CLKSRCSTS       0x20U   // Clock Source Status

#define SYSCTL_O_CPUSYSLOCK           0x0U    // Lock bit for CPUSYS registers
#define SYSCTL_O_PIEVERRADDR          0x2U    // PIE Vector Fetch Error Address register
#define SYSCTL_O_SIMRESET             0x4U    // Simulated Reset Register
#define SYSCTL_O_LPMCR                0x8U    // LPM Control Register
#define SYSCTL_O_GPIOLPMSEL0          0xAU    // GPIO LPM Wakeup select registers
#define SYSCTL_O_GPIOLPMSEL1          0xCU    // GPIO LPM Wakeup select registers
#define SYSCTL_O_TMR2CLKCTL           0xEU    // Timer2 Clock Measurement functionality control
                                              // register
#define SYSCTL_O_RESCCLR              0x10U   // Reset Cause Clear Register
#define SYSCTL_O_RESC                 0x12U   // Reset Cause register
#define SYSCTL_O_CMPSSLPMSEL          0x14U   // CMPSS LPM Wakeup select registers
#define SYSCTL_O_CLKSTOPREQ           0x16U   // Peripheral Clock Stop Request Register
#define SYSCTL_O_CLKSTOPACK           0x18U   // Peripheral Clock Stop Ackonwledge Register
#define SYSCTL_O_USER_REG1_SYSRSN     0x1AU   // Software Configurable registers reset by SYSRSn
#define SYSCTL_O_USER_REG2_SYSRSN     0x1CU   // Software Configurable registers reset by SYSRSn
#define SYSCTL_O_USER_REG1_XRSN       0x1EU   // Software Configurable registers reset by XRSn
#define SYSCTL_O_USER_REG2_XRSN       0x20U   // Software Configurable registers reset by XRSn
#define SYSCTL_O_USER_REG1_PORESETN   0x22U   // Software Configurable registers reset by PORESETn
#define SYSCTL_O_USER_REG2_PORESETN   0x24U   // Software Configurable registers reset by PORESETn
#define SYSCTL_O_USER_REG3_PORESETN   0x26U   // Software Configurable registers reset by PORESETn
#define SYSCTL_O_USER_REG4_PORESETN   0x28U   // Software Configurable registers reset by PORESETn
#define SYSCTL_O_PERCLKCR             0x3CU   // Peripheral Clock Control

#define SYSCTL_O_SCSR     0x22U   // System Control & Status Register
#define SYSCTL_O_WDCNTR   0x23U   // Watchdog Counter Register
#define SYSCTL_O_WDKEY    0x25U   // Watchdog Reset Key Register
#define SYSCTL_O_WDCR     0x29U   // Watchdog Control Register
#define SYSCTL_O_WDWCR    0x2AU   // Watchdog Windowed Control Register

#define SYSCTL_O_DMACLASRCSELLOCK   0x0U   // DMA/CLA Trigger Source Select Lock Register
#define SYSCTL_O_DMACHSRCSEL1       0x2U   // DMA Channel Trigger Source Select Register-1

#define SYSCTL_O_SYNCSELECT        0x0U   // Sync Input and Output Select Register
#define SYSCTL_O_ADCSOCOUTSELECT   0x2U   // External ADCSOC Select Register
#define SYSCTL_O_SYNCSOCLOCK       0x4U   // SYNCSEL and EXTADCSOC Select Lock register

#define SYSCTL_O_LFUCONFIG    0x0U   // LFU configuration Register
#define SYSCTL_O_LFUSTATUS    0x2U   // LFU Configuration Status Register
#define SYSCTL_O_LFU_LOCK     0x4U   // LFU Lock Configuration
#define SYSCTL_O_LFU_COMMIT   0x6U   // LFU Commit Configuration

#define SYSCTL_O_SYS_ERR_INT_FLG   0x0U   // Status of interrupts due to multiple different errors
                                          // in the system.
#define SYSCTL_O_SYS_ERR_INT_CLR   0x2U   // SYS_ERR_INT_FLG clear register
#define SYSCTL_O_SYS_ERR_INT_SET   0x4U   // SYS_ERR_INT_FLG set register
#define SYSCTL_O_SYS_ERR_MASK      0x6U   // SYS_ERR_MASK register


