#define CMPSSLITE_initFilterHigh           CMPSS_initFilterHigh
#define CMPSSLITE_initFilterLow            CMPSS_initFilterLow
#define CMPSSLITE_configureFilterInputHigh CMPSS_configureFilterInputHigh
#define CMPSSLITE_configureFilterInputLow  CMPSS_configureFilterInputLow
