#define CMPSSLITE_getDACValueLow           CMPSS_getDACValueLow
#define CMPSSLITE_clearFilterLatchHigh     CMPSS_clearFilterLatchHigh
#define CMPSSLITE_clearFilterLatchLow      CMPSS_clearFilterLatchLow
