#define DCSM_Z1_GRABSECT1R_GRAB_B0_SECT31_4_M    0x300U   // Grab Flash Bank0 Sector 31-4
#define DCSM_Z1_GRABSECT1R_GRAB_B0_SECT63_32_S   10U
#define DCSM_Z1_GRABSECT1R_GRAB_B0_SECT63_32_M   0xC00U   // Grab Flash Bank0 Sector 63-32

//*************************************************************************************************
//
// The following are defines for the bit fields in the Z1_EXEONLYSECT1R register
//
//*************************************************************************************************
#define DCSM_Z1_EXEONLYSECT1R_EXEONLY_B0_SECT0       0x1U    // Execute-Only Flash Bank0 Sector 0
#define DCSM_Z1_EXEONLYSECT1R_EXEONLY_B0_SECT1       0x2U    // Execute-Only Flash Bank0 Sector 1
#define DCSM_Z1_EXEONLYSECT1R_EXEONLY_B0_SECT2       0x4U    // Execute-Only Flash Bank0 Sector 2
#define DCSM_Z1_EXEONLYSECT1R_EXEONLY_B0_SECT3       0x8U    // Execute-Only Flash Bank0 Sector 3
#define DCSM_Z1_EXEONLYSECT1R_EXEONLY_B0_SECT31_4    0x10U   // Execute-Only Flash Bank0 Sector
                                                             // 31-4
#define DCSM_Z1_EXEONLYSECT1R_EXEONLY_B0_SECT63_32   0x20U   // Execute-Only Flash Bank0 Sector
